<?php
declare(strict_types=1);
require_once __DIR__.'/Pricing.php';
require_once __DIR__.'/Orders.php';
final class PartnerCredit
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function uuid(mixed $v):bool{return is_string($v)&&(bool)preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$v);}
    private static function text(mixed $v,int $max):string{if(!is_string($v))throw new HttpError(400,'Mã giao dịch hoặc ghi chú không hợp lệ.');$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);if($v===null||$v===''||str_contains($v,"\0")||strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2>$max)throw new HttpError(400,'Kiểm tra độ dài mã giao dịch/ghi chú.');return $v;}
    private static function amount(mixed $v):int
    {
        if(is_string($v)&&preg_match('/^-?[0-9]+$/D',$v)&&strlen(ltrim($v,'-'))<=16)$v=(int)$v;if(!is_int($v)||$v>Pricing::MAX_SAFE||$v< -Pricing::MAX_SAFE)throw new HttpError(409,'Số tiền sổ công nợ vượt phạm vi xử lý.');return $v;
    }
    private static function add(int $a,int $b):int{$out=$a+$b;if($out>Pricing::MAX_SAFE||$out< -Pricing::MAX_SAFE)throw new HttpError(409,'Tổng công nợ vượt phạm vi xử lý.');return $out;}
    public static function summary(array $entries,int $limit,?DateTimeImmutable $now=null):array
    {
        if($limit<0||$limit>1000000000000)throw new HttpError(409,'Hạn mức công nợ không hợp lệ.');$balance=0;$settled=0;foreach($entries as $e){$a=self::amount($e['amount']);$balance=self::add($balance,$a);if($a<0)$settled=self::add($settled,-$a);}if($balance<0)throw new HttpError(409,'Sổ công nợ âm; chưa hỗ trợ ví trả trước.');$charges=[];$overdue=0;$now??=new DateTimeImmutable('now',new DateTimeZone('UTC'));
        foreach($entries as $e){$amount=self::amount($e['amount']);if($amount<=0)continue;$applied=min($settled,$amount);$settled-=$applied;$outstanding=$amount-$applied;$due=$e['due_at'];if($outstanding>0&&$due!==null&&(new DateTimeImmutable($due,new DateTimeZone('UTC')))<$now)$overdue=self::add($overdue,$outstanding);$charges[]=['orderId'=>$e['order_id'],'amount'=>$amount,'outstanding'=>$outstanding,'dueAt'=>$due];}
        return ['balance'=>$balance,'available'=>max(0,$limit-$balance),'limit'=>$limit,'overdue'=>$overdue,'charges'=>$charges];
    }
    private function rows(string $id):array
    {
        $rows=$this->query('SELECT id,order_id,kind,amount,reference,note,created_at,due_at FROM jingo_partner_ledger WHERE partner_id=? ORDER BY created_at,id',[$id])->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['amount']=self::amount($r['amount']);foreach(['created_at','due_at'] as $key)if($r[$key]!==null)$r[$key]=str_replace(' ','T',$r[$key]).'Z';}unset($r);return $rows;
    }
    private function account(string $id,bool $write):array
    {
        $raw=$this->query('SELECT data FROM jingo_partners WHERE id=?'.($write?' FOR UPDATE':' LOCK IN SHARE MODE'),[$id])->fetchColumn();if($raw===false)throw new HttpError(404,'Không tìm thấy CTV.');$a=json_decode($raw,true,512,JSON_THROW_ON_ERROR);if(!is_int($a['creditLimit'] ?? null)||$a['creditLimit']<0||$a['creditLimit']>1000000000000||!is_int($a['creditDays'] ?? null)||$a['creditDays']<1||$a['creditDays']>90||!is_bool($a['creditEnabled'] ?? null))throw new HttpError(409,'Cấu hình công nợ CTV không hợp lệ.');return $a;
    }
    private function view(string $id,array $account):array{$entries=$this->rows($id);return self::summary($entries,$account['creditLimit'])+['creditEnabled'=>$account['creditEnabled'],'creditDays'=>$account['creditDays'],'entries'=>$entries];}
    public function ledger(string $id,?string $partnerId=null):array
    {
        if($partnerId!==null&&$partnerId!==$id)throw new HttpError(404,'Không tìm thấy sổ CTV.');$this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->beginTransaction();try{$a=$this->account($id,false);if($partnerId!==null&&!in_array($a['status'] ?? '',['ACTIVE','PAUSED'],true))throw new HttpError(403,'Tài khoản CTV không còn hợp lệ.');$out=$this->view($id,$a);$this->db->commit();return $out;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function charge(string $id,array $input,string $actor,?string $partnerId=null):array
    {
        if(array_diff(array_keys($input),['requestId','version','note'])||!self::uuid($input['requestId'] ?? null)||!is_int($input['version'] ?? null)||$input['version']<1||$input['version']>2147483646)throw new HttpError(400,'Yêu cầu ghi nợ không hợp lệ.');$input=['requestId'=>$input['requestId'],'version'=>$input['version'],'note'=>self::text($input['note'] ?? null,1000)];$hash=hash('sha256',json_encode(['orderId'=>$id,'action'=>'CREDIT','input'=>$input],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{
            $owner=$this->query('SELECT partner_id FROM jingo_partner_orders WHERE order_id=?',[$id])->fetchColumn();if($owner===false||$partnerId!==null&&$owner!==$partnerId)throw new HttpError(404,'Không tìm thấy đơn CTV.');$a=$this->account($owner,true);if(($a['status'] ?? '')!=='ACTIVE'||!$a['creditEnabled'])throw new HttpError(403,'CTV chưa được dùng công nợ.');if($partnerId!==null)$actor='partner:'.$partnerId;$o=$this->query('SELECT * FROM jingo_orders WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$o)throw new HttpError(404,'Không tìm thấy đơn.');
            $prior=$this->query('SELECT request_hash FROM jingo_order_actions WHERE id=?',[$input['requestId']])->fetchColumn();if($prior!==false){$ledger=$this->query("SELECT request_hash FROM jingo_partner_ledger WHERE id=? AND partner_id=? AND order_id=? AND kind='CHARGE'",[$input['requestId'],$owner,$id])->fetchColumn();if(!hash_equals($prior,$hash)||$ledger===false||!hash_equals($ledger,$hash))throw new HttpError(409,'Mã yêu cầu đã dùng.');$this->db->commit();return (new Orders($this->db))->get($id);}
            if((int)$o['version']!==$input['version']||$o['booking_status']!=='CONFIRMED'||$o['payment_status']!=='UNPAID'||$this->query('SELECT order_id FROM jingo_order_archives WHERE order_id=?',[$id])->fetchColumn())throw new HttpError(409,'Chỉ ghi nợ cho đơn CTV đã xác nhận, chưa thu tiền và chưa lưu trữ.');$summary=self::summary($this->rows($owner),$a['creditLimit']);$snapshot=json_decode($o['snapshot'],true,512,JSON_THROW_ON_ERROR);$amount=self::amount($snapshot['total']);if($amount<0)throw new HttpError(409,'Tổng đơn không hợp lệ.');if($summary['overdue']>0)throw new HttpError(409,'Có công nợ quá hạn. Vui lòng thanh toán trước khi dùng thêm hạn mức.');if($amount>$summary['available'])throw new HttpError(409,'Đơn vượt hạn mức công nợ còn lại.');
            $due=gmdate('Y-m-d H:i:s',time()+$a['creditDays']*86400);$this->query("INSERT INTO jingo_partner_ledger(id,partner_id,order_id,kind,amount,reference,note,actor_id,request_hash,due_at) VALUES (?,?,?,'CHARGE',?,?,?,?,?,?)",[$input['requestId'],$owner,$id,$amount,$o['code'],'Ghi công nợ đơn '.$o['code'],$actor,$hash,$due]);$this->query("UPDATE jingo_orders SET payment_status='CREDIT',version=version+1 WHERE id=?",[$id]);$this->query("INSERT INTO jingo_order_actions(id,order_id,request_hash,admin_id,action,order_version,data) VALUES (?,?,?,?,'CREDIT',?,?)",[$input['requestId'],$id,$hash,$actor,$input['version']+1,json_encode(['note'=>$input['note']],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'order.credit',$id]);$this->db->commit();return (new Orders($this->db))->get($id);
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if($e instanceof PDOException&&($e->errorInfo[1] ?? null)===1062)throw new HttpError(409,'Mã thao tác đã dùng.');throw $e;}
    }
    public function repay(string $id,array $input,string $actor):array
    {
        if(array_diff(array_keys($input),['requestId','amount','reference','note'])||!self::uuid($input['requestId'] ?? null)||!is_int($input['amount'] ?? null)||$input['amount']<1||$input['amount']>1000000000000)throw new HttpError(400,'Khoản trả nợ không hợp lệ.');$input=['requestId'=>$input['requestId'],'amount'=>$input['amount'],'reference'=>self::text($input['reference'] ?? null,200),'note'=>self::text($input['note'] ?? null,1000)];$reference=mb_strtoupper($input['reference'],'UTF-8');if(mb_strlen($reference,'UTF-8')>200||preg_match('/[\x00-\x1f\x7f]/u',$reference))throw new HttpError(400,'Mã giao dịch không hợp lệ.');$hash=hash('sha256',json_encode(['partnerId'=>$id,'input'=>$input],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{
            $a=$this->account($id,true);$prior=$this->query('SELECT partner_id,kind,request_hash FROM jingo_partner_ledger WHERE id=?',[$input['requestId']])->fetch(PDO::FETCH_ASSOC);if($prior){if($prior['partner_id']!==$id||$prior['kind']!=='REPAYMENT'||!hash_equals($prior['request_hash'],$hash))throw new HttpError(409,'Mã yêu cầu đã dùng.');$this->db->commit();return $this->ledger($id);}$summary=self::summary($this->rows($id),$a['creditLimit']);if($input['amount']>$summary['balance'])throw new HttpError(400,'Số tiền trả vượt công nợ. Chưa hỗ trợ ví trả trước.');$this->query("INSERT INTO jingo_payment_references(reference_hash,reference,kind,entity_id,amount) VALUES (?,?,'PARTNER_REPAYMENT',?,?)",[hash('sha256',$reference),$reference,$id,$input['amount']]);$this->query("INSERT INTO jingo_partner_ledger(id,partner_id,order_id,kind,amount,reference,note,actor_id,request_hash,due_at) VALUES (?,?,NULL,'REPAYMENT',?,?,?,?,?,NULL)",[$input['requestId'],$id,-$input['amount'],$reference,$input['note'],$actor,$hash]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'partner.repayment',$id]);$this->db->commit();return $this->ledger($id);
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if($e instanceof PDOException&&($e->errorInfo[1] ?? null)===1062)throw new HttpError(409,'Mã giao dịch hoặc yêu cầu đã dùng.');throw $e;}
    }
}
